import os
from typing import AsyncGenerator
from contextlib import asynccontextmanager

from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import StreamingResponse, JSONResponse, FileResponse
from fastapi.middleware.cors import CORSMiddleware
import anthropic

ANTHROPIC_API_KEY = os.environ.get("ANTHROPIC_API_KEY")
ANTHROPIC_BASE_URL = os.environ.get("ANTHROPIC_BASE_URL")
ANTHROPIC_WORKSPACE_ID = os.environ.get("ANTHROPIC_WORKSPACE_ID")
MODEL = "claude-opus-4-7"
MAX_TOKENS = 128000

default_headers = {}
if ANTHROPIC_WORKSPACE_ID:
    default_headers["anthropic-workspace-id"] = ANTHROPIC_WORKSPACE_ID

if ANTHROPIC_BASE_URL:
    client = anthropic.Anthropic(
        api_key=ANTHROPIC_API_KEY,
        base_url=ANTHROPIC_BASE_URL,
        default_headers=default_headers,
    )
else:
    client = anthropic.Anthropic(
        api_key=ANTHROPIC_API_KEY,
        default_headers=default_headers,
    )


@asynccontextmanager
async def lifespan(app: FastAPI):
    print(f"Started. model={MODEL} max_tokens={MAX_TOKENS}")
    yield


app = FastAPI(title="Helium Chat", lifespan=lifespan)

BASE_DIR = os.path.dirname(os.path.abspath(__file__))

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


@app.get("/")
async def serve_index():
    return FileResponse(os.path.join(BASE_DIR, "index.html"))


def format_messages(raw_messages: list[dict]) -> list[dict]:
    formatted = []
    for msg in raw_messages:
        role = msg.get("role", "user")
        content = msg.get("content", "")
        attachments = msg.get("attachments")
        if role == "assistant":
            formatted.append({"role": "assistant", "content": str(content)})
        else:
            if attachments and isinstance(attachments, dict):
                imgs = attachments.get("imgs", [])
                if imgs and isinstance(imgs, list):
                    parts = []
                    for img in imgs:
                        data_url = (
                            img.get("dataUrl", "")
                            if isinstance(img, dict)
                            else str(img)
                        )
                        if data_url.startswith("data:image/"):
                            media_type = data_url.split(";")[0].split(":")[1]
                            base64_data = data_url.split(",")[1]
                            parts.append(
                                {
                                    "type": "image",
                                    "source": {
                                        "type": "base64",
                                        "media_type": media_type,
                                        "data": base64_data,
                                    },
                                }
                            )
                    parts.append({"type": "text", "text": str(content)})
                    formatted.append({"role": "user", "content": parts})
                else:
                    formatted.append({"role": "user", "content": str(content)})
            else:
                formatted.append({"role": "user", "content": str(content)})
    return formatted


async def stream_chat(messages: list[dict]) -> AsyncGenerator[str, None]:
    try:
        with client.beta.messages.stream(
            model=MODEL,
            max_tokens=MAX_TOKENS,
            thinking={"type": "adaptive"},
            output_config={"effort": "max"},
            betas=["output-128k-2025-02-19"],
            messages=messages,
        ) as stream:
            for event in stream:
                if hasattr(event, "type"):
                    if event.type == "content_block_delta":
                        delta = event.delta
                        if hasattr(delta, "type"):
                            if delta.type == "text_delta" and hasattr(delta, "text"):
                                yield f"data: {delta.text}\n\n"
                            elif delta.type == "thinking_delta" and hasattr(
                                delta, "thinking"
                            ):
                                yield f"thinking: {delta.thinking}\n\n"
            yield "data: [DONE]\n\n"
    except Exception as e:
        yield f"data: [ERROR] {str(e)}\n\n"


@app.post("/api/chat")
async def chat(request: Request):
    try:
        body = await request.json()
        raw_messages = body.get("messages", [])
        if not raw_messages:
            raise HTTPException(status_code=400, detail="No messages provided")
        formatted = format_messages(raw_messages)
        return StreamingResponse(
            stream_chat(formatted),
            media_type="text/event-stream",
            headers={
                "Cache-Control": "no-cache",
                "Connection": "keep-alive",
                "X-Accel-Buffering": "no",
            },
        )
    except HTTPException:
        raise
    except Exception as e:
        return JSONResponse(status_code=500, content={"error": str(e)})


@app.get("/api/health")
async def health():
    return {"status": "ok", "model": MODEL, "max_tokens": MAX_TOKENS}


